import { defineMarkdownDocumentComponent } from '@comark/vue'

// Generated by the module: the component each tag renders with, keyed by the tag as written in
// documents (`foo-bar`). Global winners aren't listed: `MarkdownDocument` resolves them from the app.
// Virtual imports have to be static for the bundler to rewrite them; the file only exists in a Nuxt build.
import { components } from '#content-components'

/**
 * Renders a Comark document (`{ nodes, frontmatter, meta }`), e.g. one returned by `content.get()`,
 * with the content components baked in. A `components` prop entry replaces the one of its tag.
 */
export default defineMarkdownDocumentComponent({
  name: 'ContentDocument',
  components,
})
